mapper.select:
SELECT pa.id, #{query.date} as date, pa.bank_name as bankName, pa.account_name as accountName, pa.account_number as accountNumber, pa.currency, COALESCE(as.balance, 0) as accountBalance, sb.acc_code1 as subject, sb.acc_code2 as subSubject, COALESCE(sb.end_balance, 0) as endBalance, COALESCE(as.balance, 0) - COALESCE(sb.end_balance, 0) as differenceAmount FROM tms_payment_account pa LEFT JOIN tms_account_stream as ON as.account_number = pa.account_number AND as.currency = pa.currency AND as.date = #{query.date} LEFT JOIN tms_subject_balance sb ON sb.segment1 = '800000' AND sb.acc_code1 = pa.subject_code AND sb.acc_code2 = pa.sub_subject_code AND sb.set_of_books_id = 'HK_SOB' AND sb.period_name = ( SELECT MAX(period_name) FROM tms_subject_balance WHERE segment1 = '800000' AND acc_code1 = pa.subject_code AND acc_code2 = pa.sub_subject_code AND set_of_books_id = 'HK_SOB' )
AND pa.bank_name LIKE CONCAT('%', #{query.bankName}, '%')
AND pa.account_number = #{query.accountNumber}
AND pa.currency = #{query.currency}
AND as.balance = #{query.amount}
AND COALESCE(as.balance, 0) != COALESCE(sb.end_balance, 0)
AND COALESCE(as.balance, 0) = COALESCE(sb.end_balance, 0)
ORDER BY pa.date DESC, pa.bank_name ASC
